#!/usr/bin/env node
/**
 * Deterministic synthetic metadata-index benchmark (NOT actual full-site Pages deploy).
 * No API/network, 40k articles are NOT generated by this test.
 */
import {performance} from "node:perf_hooks";
const LOCALES=["vi","en","de","fr","es","nl","zh","pt","ko","ja"];
function measure(total){
 const start=performance.now(),size=150,groups=Object.fromEntries(LOCALES.map(l=>[l,[]]));
 for(let i=0;i<total;i++){
  const lang=LOCALES[i%10],id=String(i).padStart(6,"0");
  const row={u:"/"+lang+"/guides/topic-"+id+"/",t:"How to review a Hanoi rental motorcycle — "+id,d:"A concise example description for a simulated search metadata item; this is NOT a real published article.",type:"SUPPORT"};
  groups[lang].push(row);
 }
 let max=0,bytes=0,shards=0;
 for(const entries of Object.values(groups)){
  for(let i=0;i<entries.length;i+=size){
   const json=JSON.stringify(entries.slice(i,i+size));
   const length=Buffer.byteLength(json);
   max=Math.max(max,length);bytes+=length;shards++;
  }
 }
 const duration=Number((performance.now()-start).toFixed(1));
 return{synthetic_items:total,locales:LOCALES.length,articles_per_locale:total/10,shard_max_items:size,shard_count:shards,max_shard_bytes:max,total_metadata_bytes:bytes,index_generation_ms_local:duration,heap_used_MB_after:Number((process.memoryUsage().heapUsed/1024/1024).toFixed(1))};
}
const results=[10000,40000].map(measure);
console.log(JSON.stringify({scope:"SYNTHETIC_METADATA_INDEX_ONLY",platform:"Node "+process.version,mode:"single-process-memory-only",search_algorithm:"on-demand fetch of metadata shards in a selected language; NOT article bodies",results,limitations:["No real 40k HTML pages generated or deployed","No GitHub Pages cold-cache or mobile network speed measured","No Core Web Vitals scores measured","Metadata search still scans selected locale shards on a query; optimize token inverted index if one locale grows beyond acceptable mobile cost"]},null,2));
if(results.some(x=>x.max_shard_bytes>100000))process.exitCode=1;
